import ee
import math

def safe_init():
    try:
        ee.Initialize(project='earthsense-436113')
    except Exception:
        try:
            ee.Initialize()
        except Exception:
            print("Initialization failed.")
            print("D")
            raise

safe_init()

# 1. Geometry & Time Definitions
boston_pt = ee.Geometry.Point([-71.0589, 42.3601])
roi = boston_pt.buffer(10000)  # 10 km buffer
start = '2019-01-29'
end = '2019-02-06'  # end-exclusive, includes up to Feb 5

def get_collection_and_band():
    # Primary: ERA5-Land Daily Aggregated
    col1 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR').filterDate(start, end).filterBounds(roi)
    if col1.size().getInfo() > 0:
        bands = ee.Image(col1.first()).bandNames().getInfo()
        band = 'temperature_2m_max' if 'temperature_2m_max' in bands else None
        if band:
            return col1, 'ECMWF/ERA5_LAND/DAILY_AGGR', band, 9000
    # Fallback: ERA5 Daily
    col2 = ee.ImageCollection('ECMWF/ERA5/DAILY').filterDate(start, end).filterBounds(roi)
    if col2.size().getInfo() > 0:
        bands = ee.Image(col2.first()).bandNames().getInfo()
        band = 'maximum_2m_air_temperature' if 'maximum_2m_air_temperature' in bands else None
        if band:
            return col2, 'ECMWF/ERA5/DAILY', band, 30000
    return None, None, None, None

try:
    col, dataset_name, band_name, scale = get_collection_and_band()
    if col is None:
        print("Dataset: None, Images: 0")
        print("C1")
    else:
        n = col.size().getInfo()
        print(f"Dataset: {dataset_name}, Band: {band_name}, Images: {n}")
        if n == 0:
            print("C1")
        else:
            lst = col.toList(n)
            records = []
            valid_count = 0
            invalid_flag = False
            min_val = None
            max_val = None
            min_date = None
            max_date = None

            for i in range(n):
                img = ee.Image(lst.get(i))
                date = img.date().format('YYYY-MM-dd').getInfo()
                tC = img.select(band_name).subtract(273.15).rename('tmaxC')
                count = tC.reduceRegion(
                    reducer=ee.Reducer.count(),
                    geometry=roi,
                    scale=scale,
                    maxPixels=1e9
                ).get('tmaxC').getInfo()
                if (count is None) or (count == 0):
                    records.append((date, None, 0))
                    continue
                meanC = tC.reduceRegion(
                    reducer=ee.Reducer.mean(),
                    geometry=roi,
                    scale=scale,
                    maxPixels=1e9
                ).get('tmaxC').getInfo()
                if (meanC is None) or (isinstance(meanC, float) and (math.isnan(meanC) or meanC < -100 or meanC > 60)):
                    invalid_flag = True
                    records.append((date, None, count))
                    continue
                valid_count += 1
                records.append((date, meanC, count))
                if (min_val is None) or (meanC < min_val):
                    min_val = meanC; min_date = date
                if (max_val is None) or (meanC > max_val):
                    max_val = meanC; max_date = date

            # Print concise per-day stats (<=20 lines total)
            for (d, v, c) in records:
                if v is None:
                    print(f"{d}: TmaxC=None, px={c}")
                else:
                    print(f"{d}: TmaxC={v:.2f}°C, px={c}")

            if valid_count == 0:
                print("C2")
            elif invalid_flag or (min_val is None) or (max_val is None):
                print("C3")
            else:
                diff = max_val - min_val
                if diff is None or (isinstance(diff, float) and math.isnan(diff)):
                    print("C3")
                else:
                    print(f"Range: min={min_val:.2f}°C on {min_date}, max={max_val:.2f}°C on {max_date}, diff={diff:.2f}°C")
                    print("A" if diff >= 22.0 else "B")
except ee.EEException:
    print("D")
except Exception:
    print("D")
